636	
637	
638	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
639	    @Override
640	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
641	        Owner owner = this.clinicService.findOwnerById(ownerId);
642	        if (owner != null) {
